#include <stdio.h>
#include <limits.h>

int main() {
    int R, N;
    if (scanf("%d %d", &R, &N) != 2) return 0;

    int preco[101];
    for (int i = 1; i <= 100; i++) {
        preco[i] = INT_MAX;
    }

    for (int i = 0; i < N; i++) {
        int t, p;
        scanf("%d %d", &t, &p);
        if (p < preco[t]) {
            preco[t] = p;
        }
    }

    int precos[101], m = 0;
    for (int i = 1; i <= 100; i++) {
        if (preco[i] != INT_MAX) {
            precos[m++] = preco[i];
        }
    }

    for (int i = 0; i < m - 1; i++) {
        for (int j = i + 1; j < m; j++) {
            if (precos[i] > precos[j]) {
                int tmp = precos[i];
                precos[i] = precos[j];
                precos[j] = tmp;
            }
        }
    }

    int tipos = 0;
    for (int i = 0; i < m; i++) {
        if (R >= precos[i]) {
            R -= precos[i];
            tipos++;
        } else {
            break;
        }
    }

    printf("%d\n", tipos);
    return 0;
}
